<template> <form @submit.prevent="submitLogin"> <input v-model="username" placeholder="Username"/> <input type="password" v-model="password" placeholder="Password"/> <button type="submit">Login</button> </form> </template> <script> import authService from '@/services/auth'; export default { data() { return { username: '', password: '', error: '' }; }, methods: { async submitLogin() { try { const response = await authService.login({ username: this.username, password: this.password }); localStorage.setItem('access_token', response.data.access); localStorage.setItem('refresh_token', response.data.refresh); this.$router.push('/dashboard'); } catch (err) { this.error = 'Invalid credentials'; } } } } </script>
